import {models,calculate,VERSION} from './models.js';
const $=id=>document.getElementById(id);let currentResult=null,lastUnit='in';
const format=(x,n=2)=>x.toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
const fill=(id,values)=>{$(id).replaceChildren();for(const v of [...new Set(values)])$(id).add(new Option(v,v));};
function reset(){currentResult=null;$('answer').hidden=true;$('empty').hidden=false;$('error').hidden=true;}
function details(){const m=models.find(x=>x.id===$('species').value);$('scientific').textContent=m.scientific;$('range').textContent=`Sample DBH range: ${format(m.range[0])}–${format(m.range[1])} in / ${format(m.range[0]*2.54)}–${format(m.range[1]*2.54)} cm.`;$('location-note').textContent=`${m.region} region · ${m.division} Forest Division`;const h=m.height;const htext=h.type==='log'?`${h.a} × ln(DBH in cm) − ${Math.abs(h.b)}`:`${h.a} × (DBH in cm)² + ${h.b} × DBH in cm ${h.c<0?'−':'+'} ${Math.abs(h.c)}`;const excel=m.originalSource?` Original workbook: ${m.originalSource.file}, sheet ${m.originalSource.sheet}. All ${m.originalSource.checked} stored calculation results match the original formula. Earlier summary discrepancies are resolved against this original calculation sheet.`:m.excelChecks?` All ${m.excelChecks.n} available Excel values checked are consistent with the source precision.`:' No corresponding Excel comparison column was available.';$('equation').textContent=`Table ${m.id} · ${m.division} · ${m.forest} · ${m.species}. Height (ft) = [${htext}] × 3.28. Volume (ft³) = ${m.v[0]} + ${m.v[1]} × H ${m.v[2]<0?'−':'+'} ${Math.abs(m.v[2])} × D² + ${m.v[3]} × D² × H / 100, where D is inches and H is feet. All ${m.wordChecks} printed height–volume pairs are consistent after accounting for rounded diameter labels.${excel} Source sample range: ${m.sampleRange[0]}–${m.sampleRange[1]} ${m.sampleUnit}. Volume conversion: 1 ft³ = 0.028316846592 m³. Source height conversion uses 3.28; metric height display uses 0.3048 m per foot.`;reset();}
function species(){ $('species').replaceChildren();for(const m of models.filter(x=>x.region===$('region').value&&x.division===$('division').value&&x.forest===$('forest').value))$('species').add(new Option(m.species,m.id));details();}
function locations(){fill('forest',models.filter(m=>m.region===$('region').value&&m.division===$('division').value).map(m=>m.forest));species();}
function divisions(){fill('division',models.filter(m=>m.region===$('region').value).map(m=>m.division));locations();}
$('region').addEventListener('change',divisions);$('division').addEventListener('change',locations);$('forest').addEventListener('change',species);$('species').addEventListener('change',details);$('diameter').addEventListener('input',reset);
$('unit').addEventListener('change',()=>{let value=Number($('diameter').value);if($('diameter').value&&Number.isFinite(value))$('diameter').value=String(lastUnit==='in'?value*2.54:value/2.54);lastUnit=$('unit').value;reset();});
function show(id,value,unit){const r=calculate(id,value,unit),m=models.find(x=>x.id===id);$('region').value=m.region;divisions();$('division').value=m.division;locations();$('forest').value=m.forest;species();$('species').value=id;details();$('diameter').value=String(value);$('unit').value=unit;lastUnit=unit;$('cft').textContent=format(r.cubicFeet);$('m3').textContent=format(r.cubicMetres,3);$('used').textContent=`${format(r.inches)} in · ${format(r.cm)} cm`;$('height').textContent=`${format(r.heightFeet,1)} ft · ${format(r.heightMetres,1)} m`;$('result-label').textContent=`${m.species} · ${m.forest}`;$('result-reference').textContent=`${m.region} · ${m.division} Forest Division · Table ${m.id} · Version 1.1 · Equation set ${VERSION} · ${new Date().toLocaleDateString('en-GB')}`;$('empty').hidden=true;$('answer').hidden=false;currentResult=r;return {...r,version:VERSION,region:m.region,division:m.division,location:m.forest};}
$('calculator').addEventListener('submit',e=>{e.preventDefault();try{show($('species').value,Number($('diameter').value),$('unit').value)}catch(e){reset();$('error').textContent=e.message;$('error').hidden=false;}});$('print').addEventListener('click',()=>{if(currentResult){document.body.dataset.print="single";window.print()}});fill('region',models.map(m=>m.region));divisions();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'calculate_tree_volume',description:'Calculate and display under-bark stem volume using a Version 1 local table in Malakand or Hazara. Rejects out-of-range diameters.',inputSchema:{type:'object',properties:{modelId:{type:'string',enum:models.map(m=>m.id)},dbh:{type:'number',exclusiveMinimum:0},unit:{type:'string',enum:['in','cm']}},required:['modelId','dbh','unit'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({modelId,dbh,unit})=>show(modelId,dbh,unit)})).catch(()=>{});}catch{}}
